def load(name):
    with open(RUN_DIR / name, encoding="utf-8") as f:
        return json.load(f)


def classify(text, mapping):
    if text in mapping:
        return mapping[text]
    if text:
        print(f"[warning] 未分類の原文（辞書に無い）: {text!r}", file=sys.stderr)
    return None


def shape_of(parcel, start_ledger):
    x = start_ledger.get(parcel)
    if not x:
        return "不明"
    if x.get("tenant"):
        return "借家がある区画"
    if x.get("building") and x["building"] != x["land"]:
        return "借地の区画"
    return "所有者が使っている区画"


def tally_by(items, key_fn, cat_fn):
    """items をkey_fnでグループ化し、各グループでcat_fnの分類コードを集計する。"""
    groups = defaultdict(Counter)
    ns = Counter()
    for it in items:
        k = key_fn(it)
        c = cat_fn(it)
        groups[k][c] += 1
        ns[k] += 1
    return groups, ns


def print_group_table(groups, ns, order=None):
    keys = order or sorted(ns.keys(), key=lambda k: -ns[k])
    for k in keys:
        n = ns[k]
        print(f"  {k}  n={n}")
        for cat in [1, 2, 3, 4]:
            c = groups[k].get(cat, 0)
            pct = f"{c / n * 100:.1f}%" if n else "-"
            print(f"    {CAT_LABEL[cat]}: {c} ({pct})")


def section_a_decline(offers):
    print("\n" + "=" * 70)
    print("(a) 断り理由 decline_reason")
    print("=" * 70)
    declined = [o for o in offers if not o["accepted"]]
    filled = [o for o in declined if o.get("decline_reason")]
    print(f"提示総数: {len(offers)}  断り: {len(declined)}  記入あり: {len(filled)}")

    kind_all = Counter(o["kind"] for o in declined)
    kind_filled = Counter(o["kind"] for o in filled)
    print("種別内訳（断り全件 / うち記入あり）:")
    for k in ["土地", "建物", "両方"]:
        print(f"  {k}: {kind_all.get(k, 0)} / {kind_filled.get(k, 0)}")

    loc_all = Counter(o["to_in_town"] for o in declined)
    loc_filled = Counter(o["to_in_town"] for o in filled)
    print("提示先内訳（断り全件 / うち記入あり）:")
    print(f"  町にいる人: {loc_all.get(True, 0)} / {loc_filled.get(True, 0)}")
    print(f"  町にいない所有者: {loc_all.get(False, 0)} / {loc_filled.get(False, 0)}")

    cat_fn = lambda o: classify(o["decline_reason"], DECLINE_CATEGORY)

    print("\n-- 全体の分類 --")
    tally = Counter(cat_fn(o) for o in filled)
    for cat in [1, 2, 3, 4]:
        c = tally.get(cat, 0)
        print(f"  {CAT_LABEL[cat]}: {c} ({c / len(filled) * 100:.1f}%)")

    print("\n-- 種別ごとの分類（土地だけ／建物だけ／両方） --")
    groups, ns = tally_by(filled, lambda o: o["kind"], cat_fn)
    print_group_table(groups, ns, order=["土地", "建物", "両方"])

    print("\n-- 提示先ごとの分類（町にいる人／町にいない所有者） --")
    groups, ns = tally_by(filled, lambda o: "町にいる人" if o["to_in_town"] else "町にいない所有者", cat_fn)
    print_group_table(groups, ns, order=["町にいる人", "町にいない所有者"])

    return filled, cat_fn


def section_b_listing(decisions):
    print("\n" + "=" * 70)
    print("(b) 出品理由 listing_reasons")
    print("=" * 70)
    rows = []
    for d in decisions:
        lr = d.get("listing_reasons") or {}
        lc = d.get("listings") or {}
        for parcel, txt in lr.items():
            rows.append({
                "month": d["step"], "who": d["name"], "in_town": d["in_town"],
                "parcel": parcel, "choice": lc.get(parcel), "text": txt,
            })
    filled = [r for r in rows if r["text"]]
    print(f"判断総数: {len(rows)}  記入あり: {len(filled)}")

    choice_maps = {
        "土地だけ": LISTING_LAND_CATEGORY,
        "建物だけ": LISTING_BUILDING_CATEGORY,
        "両方": LISTING_BOTH_CATEGORY,
        "出さない": LISTING_NONE_CATEGORY,
    }
    for choice, mapping in choice_maps.items():
        subset = [r for r in filled if r["choice"] == choice]
        n_all = sum(1 for r in rows if r["choice"] == choice)
        print(f"\n-- {choice}（全{n_all}件・記入{len(subset)}件） --")
        tally = Counter(classify(r["text"], mapping) for r in subset)
        for cat in [1, 2, 3, 4]:
            c = tally.get(cat, 0)
            pct = f"{c / len(subset) * 100:.1f}%" if subset else "-"
            print(f"  {CAT_LABEL[cat]}: {c} ({pct})")
    return rows, filled


def section_cde_words(offers, decisions, utterances):
    print("\n" + "=" * 70)
    print("(c)(d)(e) X社の条件文の型・海外語・金銭系語")
    print("=" * 70)

    texts = [o["text"] for o in offers]
    print(f"X社の提示文 {len(texts)}件のうち：")
    for w in ["支援", "譲渡", "維持", "継続", "管理", "改修", "対価", "金額", "価格", "費用"]:
        n = sum(1 for t in texts if w in t)
        print(f"  「{w}」を含む: {n}件")

    phase_kind = defaultdict(Counter)
    for o in offers:
        phase = "初期(1-12月)" if o["step"] <= 12 else ("中期(13-24月)" if o["step"] <= 24 else "後期(25-36月)")
        phase_kind[phase][o["kind"]] += 1
    print("\n時期別の種別内訳:")
    for phase in ["初期(1-12月)", "中期(13-24月)", "後期(25-36月)"]:
        print(f"  {phase}: {dict(phase_kind[phase])}")

    def count_any(items, get_text, words):
        checked = 0
        hit = 0
        for it in items:
            t = get_text(it)
            if not t:
                continue
            checked += 1
            if any(w in t for w in words):
                hit += 1
        return checked, hit

    decl_texts = [o for o in offers if not o["accepted"]]
    listing_rows = []
    for d in decisions:
        for parcel, txt in (d.get("listing_reasons") or {}).items():
            listing_rows.append(txt)
    sell_rows = [d.get("sell_reason", "") for d in decisions if d.get("offer")]
    thought_rows = [u.get("thought", "") for u in utterances]
    utter_rows = [u["text"] for u in utterances]
    acq_rows = [o["text"] for o in offers]

    print("\n海外語（vocab_frozen_before_the_run.foreign）:")
    for label, items, get_text in [
        ("decline_reason", decl_texts, lambda o: o.get("decline_reason", "")),
        ("listing_reason", listing_rows, lambda t: t),
        ("sell_reason", sell_rows, lambda t: t),
        ("utterances", utter_rows, lambda t: t),
        ("thoughts", thought_rows, lambda t: t),
        ("acquirer_offer_text", acq_rows, lambda t: t),
    ]:
        checked, hit = count_any(items, get_text, FOREIGN_WORDS)
        print(f"  {label}: {hit}/{checked}")

    print("\n金銭系語（vocab_frozen_before_the_run.money）:")
    for label, items, get_text in [
        ("decline_reason", decl_texts, lambda o: o.get("decline_reason", "")),
        ("listing_reason", listing_rows, lambda t: t),
        ("sell_reason", sell_rows, lambda t: t),
        ("utterances", utter_rows, lambda t: t),
        ("thoughts", thought_rows, lambda t: t),
        ("acquirer_offer_text", acq_rows, lambda t: t),
    ]:
        checked, hit = count_any(items, get_text, MONEY_WORDS)
        print(f"  {label}: {hit}/{checked}")


def section_f_sold(transfers, decisions):
    print("\n" + "=" * 70)
    print("(f) 売った5件の全件詳細")
    print("=" * 70)
    for t in transfers:
        step, agent = t["step"], t["agent_id"]
        d = next((d for d in decisions if d["step"] == step and d["agent_id"] == agent), None)
        print(f"\n-- 第{step}月 {t['name']}（{t['parcel']}・{t['kind']}） --")
        print(f"  left_town={t['left_town']} was_user={t['was_user']} user_after={t.get('user_after')}")
        if d:
            print(f"  offer: {d.get('offer')}")
            print(f"  sell_reason: {d.get('sell_reason')}")
            print(f"  thought: {d.get('thought')}")


def section_g_v9_specific(offers, notices, cat_fn):
    print("\n" + "=" * 70)
    print("(g) v9固有の観測（借家区画／町にいない所有者／通知0件）")
    print("=" * 70)

    ledger_by_step = load("ledger_by_step.json")
    start_ledger = {x["parcel"]: x for x in ledger_by_step[0]["rows"]}
    shapes = {p: shape_of(p, start_ledger) for p in start_ledger}
    shape_count = Counter(shapes.values())
    print("区画の権利の形（開始時点・ledger_by_step.json step=1基準）:")
    for k, v in shape_count.items():
        print(f"  {k}: {v}区画")
    print("  ※ 借家がある区画は世界設計の記述『9区画』とは一致しない"
          "（駐車場の運営会社2区画を含めるとコードの shape() 定義では11区画になる）。")

    declined = [o for o in offers if not o["accepted"] and o.get("decline_reason")]
    groups, ns = tally_by(declined, lambda o: shapes.get(o["parcel"], "不明"), cat_fn)
    print("\n-- 権利の形ごとの断り理由の分類 --")
    print_group_table(groups, ns, order=["借家がある区画", "借地の区画", "所有者が使っている区画"])

    print("\n-- 語彙比較（町にいる人 vs 町にいない所有者、断り理由に占める割合） --")
    town_texts = [o["decline_reason"] for o in declined if o["to_in_town"]]
    absentee_texts = [o["decline_reason"] for o in declined if not o["to_in_town"]]
    for w in ["支援内容", "条件", "生活", "介護", "愛着", "学区", "対価", "関係を維持",
              "関係維持", "具体的", "管理", "海外", "組合", "経営"]:
        t = sum(1 for x in town_texts if w in x)
        a = sum(1 for x in absentee_texts if w in x)
        print(f"  「{w}」  町内 {t}/{len(town_texts)} ({t/len(town_texts)*100:.1f}%)"
              f"   町外 {a}/{len(absentee_texts)} ({a/len(absentee_texts)*100:.1f}%)")

    print(f"\n-- 使用者への通知 --  {len(notices)}件（0件を確認）")


def main():
    offers = load("offers.json")
    decisions = load("decisions.json")
    utterances = load("utterances.json")
    transfers = load("transfers.json")
    notices = load("notices.json")

    filled_declines, cat_fn = section_a_decline(offers)
    section_b_listing(decisions)
    section_cde_words(offers, decisions, utterances)
    section_f_sold(transfers, decisions)
    section_g_v9_specific(offers, notices, cat_fn)


if __name__ == "__main__":
    main()
